/* From Uiverse.io by vinodjangid07 - Tags: button, hover, trash, delete */
.__UIV_SCOPE__ .button {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background-color: rgb(20, 20, 20);
  border: none;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.164);
  cursor: pointer;
  transition-duration: .3s;
  overflow: hidden;
  position: relative;
}

.__UIV_SCOPE__ .svgIcon {
  width: 12px;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .svgIcon path {
  fill: white;
}

.__UIV_SCOPE__ .button:hover {
  width: 140px;
  border-radius: 50px;
  transition-duration: .3s;
  background-color: rgb(255, 69, 69);
  align-items: center;
}

.__UIV_SCOPE__ .button:hover .svgIcon {
  width: 50px;
  transition-duration: .3s;
  transform: translateY(60%);
}

.__UIV_SCOPE__ .button::before {
  position: absolute;
  top: -20px;
  content: "Delete";
  color: white;
  transition-duration: .3s;
  font-size: 2px;
}

.__UIV_SCOPE__ .button:hover::before {
  font-size: 13px;
  opacity: 1;
  transform: translateY(30px);
  transition-duration: .3s;
}
